Here is a comprehensive pytest suite. It includes a helper to validate orderings (since valid topological sorts are often non-unique), and it covers happy paths, edge cases, and erroneous inputs—including the fact that the provided implementation does **not** detect cycles and instead returns an invalid ordering.

```python
import pytest

# -----------------------------------------------------------------------------
# Function under test
# -----------------------------------------------------------------------------
def topological_sort(graph: dict) -> list:
    visited = set()
    result = []
    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in graph.get(node, []):
            dfs(neighbor)
        result.append(node)
    for node in graph:
        dfs(node)
    return result[::-1]


# -----------------------------------------------------------------------------
# Validation helper
# -----------------------------------------------------------------------------
def _is_valid_topological_order(graph: dict, order: list) -> bool:
    """
    Checks that `order` is a valid topological sort of `graph`.
    Assumes an edge u -> v means "u must come before v".
    """
    if not isinstance(order, list):
        return False

    # All nodes mentioned anywhere in the graph
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        all_nodes.update(neighbors)

    if set(order) != all_nodes or len(order) != len(all_nodes):
        return False

    pos = {node: idx for idx, node in enumerate(order)}
    for u, neighbors in graph.items():
        for v in neighbors:
            if pos[u] > pos[v]:   # prerequisite appears after dependent
                return False
    return True


# -----------------------------------------------------------------------------
# Happy path tests
# -----------------------------------------------------------------------------
class TestTopologicalSortHappyPath:
    def test_empty_graph(self):
        assert topological_sort({}) == []

    def test_single_node_no_edges(self):
        graph = {"A": []}
        result = topological_sort(graph)
        assert result == ["A"]
        assert _is_valid_topological_order(graph, result)

    def test_linear_chain(self):
        graph = {"A": ["B"], "B": ["C"], "C": []}
        result = topological_sort(graph)
        # Only one valid order for a strict chain
        assert result == ["A", "B", "C"]
        assert _is_valid_topological_order(graph, result)

    def test_diamond(self):
        graph = {
            "A": ["B", "C"],
            "B": ["D"],
            "C": ["D"],
            "D": [],
        }
        result = topological_sort(graph)
        assert _is_valid_topological_order(graph, result)
        pos = {node: idx for idx, node in enumerate(result)}
        assert pos["A"] < pos["B"] < pos["D"]
        assert pos["A"] < pos["C"] < pos["D"]

    def test_multiple_independent_nodes(self):
        graph = {"A": [], "B": [], "C": []}
        result = topological_sort(graph)
        assert _is_valid_topological_order(graph, result)
        assert set(result) == {"A", "B", "C"}

    def test_complex_dag(self):
        graph = {
            "A": ["B", "C"],
            "B": ["D"],
            "C": ["D", "E"],
            "D": ["F"],
            "E": ["F"],
            "F": [],
        }
        result = topological_sort(graph)
        assert _is_valid_topological_order(graph, result)


# -----------------------------------------------------------------------------
# Edge case tests
# -----------------------------------------------------------------------------
class TestTopologicalSortEdgeCases:
    def test_disconnected_components(self):
        graph = {
            "A": ["B"],
            "B": [],
            "C": ["D"],
            "D": [],
        }
        result = topological_sort(graph)
        assert _is_valid_topological_order(graph, result)
        pos = {node: idx for idx, node in enumerate(result)}
        assert pos["A"] < pos["B"]
        assert pos["C"] < pos["D"]

    def test_node_only_appears_as_dependency(self):
        """
        If a node is listed as a neighbor but is not a top-level key,
        DFS still reaches it. Edge direction: A -> B means A before B.
        """
        graph = {"A": ["B"]}
        result = topological_sort(graph)
        assert result == ["A", "B"]
        assert _is_valid_topological_order(graph, result)

    def test_duplicate_edges(self):
        graph = {"A": ["B", "B", "C"], "B": ["C"], "C": []}
        result = topological_sort(graph)
        assert _is_valid_topological_order(graph, result)

    def test_self_loop_does_not_crash(self):
        """
        A self-loop is an invalid DAG, but the current implementation
        silently treats the already-visited neighbor as a no-op.
        """
        graph = {"A": ["A"]}
        result = topological_sort(graph)
        assert result == ["A"]


# -----------------------------------------------------------------------------
# Error / misuse tests
# -----------------------------------------------------------------------------
class TestTopologicalSortErrorCases:
    def test_two_node_cycle_does_not_raise(self):
        """
        The function lacks cycle detection. It returns without crashing,
        but the produced ordering is invalid.
        """
        graph = {"A": ["B"], "B": ["A"]}
        result = topological_sort(graph)
        assert set(result) == {"A", "B"}
        assert not _is_valid_topological_order(graph, result)
        # Deterministic given dict insertion order
        assert result == ["A", "B"]

    def test_three_node_cycle_does_not_raise(self):
        graph = {"A": ["B"], "B": ["C"], "C": ["A"]}
        result = topological_sort(graph)
        assert set(result) == {"A", "B", "C"}
        assert not _is_valid_topological_order(graph, result)

    def test_invalid_input_none(self):
        with pytest.raises(AttributeError):
            topological_sort(None)

    def test_invalid_input_string(self):
        with pytest.raises(AttributeError):
            topological_sort("not a dict")

    def test_invalid_input_list(self):
        with pytest.raises(AttributeError):
            topological_sort(["A", "B"])
```

### Key points about the suite
* **Non-deterministic orders:** For graphs where multiple valid orderings exist (e.g., the diamond or disconnected components), the tests validate the result using a helper rather than asserting an exact list.
* **Cycles:** The implementation does **not** detect cycles. The error-case tests document this behavior by asserting that the function returns an invalid ordering instead of raising an exception.
* **Edge targets that are not keys:** The function still visits nodes that appear only as neighbors, so the test verifies the sort remains valid.
* **Invalid types:** `None`, strings, and lists all trigger an `AttributeError` because the code tries to call `.get` on a non-dict.
